#define protected public
#include "sid.h"
#undef protected
#include <cstdio>
int main() {
  reSID::SID sid;
  std::printf("// The 6581 filter's VCR current table (reSID's Filter::vcr_n_Ids_term), as filter.cc's constructor made it\n"
    "// with the C library's exp() and log1p() of macOS (the legacy build's): generated by tools/dump-vcr-table.sh, so that\n"
    "// every platform plays the same table whatever its math library rounds. reSID: GPL-2.0-or-later, Dag Lem.\n"
    "static const unsigned short vcr_n_ids_term_table[1 << 16] = {\n");
  for (int i = 0; i < (1 << 16); i++) std::printf("%u,%s", (unsigned)reSID::Filter::vcr_n_Ids_term[i], (i % 16 == 15) ? "\n" : "");
  std::printf("};\n");
}
